6	export class Scene {
7	  readonly three: THREE.Scene;
8	  private _objects = new Map<string, SceneObject>();
9	  
10	  private _rawObjects = new Map<string, THREE.Object3D | Record<string, unknown>>();
11	  private _objectRegisteredListeners = new Set<(id: string) => void>();
12	  private _context: SceneObjectContext | null = null;
13	  constructor() {
14	    this.three = new THREE.Scene();
15	  }
16	
17	  setContext(context: SceneObjectContext): void {
18	    this._context = context;
19	  }
20	
21	  get context(): SceneObjectContext | null {
22	    return this._context;
23	  }
24	
25	  async addObject(id: string, object: SceneObject): Promise<void> {
26	    if (!this._context) return;
27	    this._objects.set(id, object);
28	    object.init(this._context);
29	    const runResult = object.runObject();
30	    if (runResult && runResult instanceof Promise) await runResult;
31	    this._emitObjectRegistered(id);
32	  }
33	
34	  
35	  registerObject(id: string, obj: THREE.Object3D | Record<string, unknown>): void {
36	    this._rawObjects.set(id, obj);
37	    this._emitObjectRegistered(id);
38	  }
39	
40	  unregisterObject(id: string): void {
41	    this._rawObjects.delete(id);
42	  }
43	
44	  onObjectRegistered(listener: (id: string) => void): () => void {
45	    this._objectRegisteredListeners.add(listener);
46	    return () => {
47	      this._objectRegisteredListeners.delete(listener);
48	    };
49	  }
50	
51	  
52	  getObject(id: string): THREE.Object3D | Record<string, unknown> | null {
53	    return this._rawObjects.get(id)
54	      ?? this._objects.get(id)?.getAnimationTarget()
55	      ?? null;
56	  }
57	
58	  getSceneObject(id: string): SceneObject | null {
59	    return this._objects.get(id) ?? null;
60	  }
61	
62	  removeObject(id: string): void {
63	    const object = this._objects.get(id);
64	    if (!object) return;
65	    object.dispose();
66	    this._objects.delete(id);
67	  }
68	
69	  getObjectIds(): string[] {
70	    return [
71	      ...this._objects.keys(),
72	      ...this._rawObjects.keys(),
73	    ];
74	  }
75	
76	  
77	  getAll(): Record<string, SceneObject> {
78	    return Object.fromEntries(this._objects);
79	  }
80	
81	  private _bloomRootsCache = new Set<THREE.Object3D>();
82	
83	  getBloomRoots(): Set<THREE.Object3D> {
84	    const roots = this._bloomRootsCache;
85	    roots.clear();
86	    for (const obj of this._objects.values()) {
87	      if (obj.isDisposed || !obj.getVisibleState() || !obj.getBloomEnabled()) continue;
88	      const target = obj.getBloomTarget();
89	      if (target && target.parent) roots.add(target);
90	    }
91	    return roots;
92	  }
93	
94	  update(deltaTime: number): void {
95	    for (const obj of this._objects.values()) {
96	      if (!obj.isDisposed) obj.runUpdate(deltaTime);
97	    }
98	  }
99	
100	  dispose(): void {
101	    for (const obj of this._objects.values()) {
102	      obj.dispose();
103	    }
104	    this._objects.clear();
105	    this._rawObjects.clear();
106	    this._objectRegisteredListeners.clear();
107	    this.three.traverse((child) => {
108	      if (!(child instanceof THREE.Mesh)) return;
109	      child.geometry?.dispose();
110	      const mats = Array.isArray(child.material)
111	        ? child.material
112	        : [child.material];
113	      for (const material of mats) {
114	        material?.dispose();
115	      }
116	    });
117	    this._context = null;
118	  }
119	
120	  private _emitObjectRegistered(id: string): void {
121	    for (const listener of this._objectRegisteredListeners) {
122	      try {
123	        listener(id);
124	      } catch (error) {
125	        console.warn("[Scene._emitObjectRegistered] Listener failed.", error);
126	      }
127	    }
128	  }
129	}
