569	  private _resolveDebugTrackSnapshots(
570	    sheetId: MainTheatreSheetId,
571	    sheetPosition: number,
572	  ): MainSceneDebugSnapshot["tracks"] {
573	    const tracksByObject = this._readSheetTracksByObject(sheetId);
574	    const objectTracks = tracksByObject?.[MAIN_THEATRE_OBJECT_ID];
575	    if (!objectTracks || typeof objectTracks !== "object") return [];
576	    const trackData = (objectTracks as Record<string, unknown>).trackData;
577	    if (!trackData || typeof trackData !== "object") return [];
578	    const snapshots: MainSceneDebugTrackSnapshot[] = [];
579	    Object.values(trackData as Record<string, unknown>).forEach(
580	      (trackState) => {
581	        if (!trackState || typeof trackState !== "object") return;
582	        const debugName = (trackState as Record<string, unknown>).__debugName;
583	        if (
584	          typeof debugName !== "string" ||
585	          !MAIN_CAMERA_TRACK_DEBUG_NAMES.some((path) =>
586	            debugName.includes(path),
587	          )
588	        ) {
589	          return;
590	        }
591	        const keyframes = (trackState as Record<string, unknown>).keyframes;
592	        if (!Array.isArray(keyframes) || keyframes.length === 0) return;
593	        const positions = keyframes
594	          .map((keyframe) => {
595	            if (!keyframe || typeof keyframe !== "object") return null;
596	            const position = (keyframe as Record<string, unknown>).position;
597	            return typeof position === "number" && Number.isFinite(position)
598	              ? position
599	              : null;
600	          })
601	          .filter((position): position is number => position != null);
602	        if (positions.length === 0) return;
603	        snapshots.push({
604	          track: debugName.replace("orbitCamera:", ""),
605	          keyframeCount: positions.length,
606	          fromKeyframeIndex: this._resolveDebugFromKeyframeIndex(
607	            positions,
608	            sheetPosition,
609	          ),
610	          toKeyframeIndex: this._resolveDebugToKeyframeIndex(
611	            positions,
612	            sheetPosition,
613	          ),
614	        });
615	      },
616	    );
617	    return snapshots;
618	  }
619	
620	  private _resolveDebugFromKeyframeIndex(
621	    positions: readonly number[],
622	    sheetPosition: number,
623	  ): number | null {
624	    if (positions.length === 0) return null;
625	    for (let index = positions.length - 1; index >= 0; index -= 1) {
626	      if (sheetPosition >= positions[index]) return index;
627	    }
628	    return null;
629	  }
630	
631	  private _resolveDebugToKeyframeIndex(
632	    positions: readonly number[],
633	    sheetPosition: number,
634	  ): number | null {
635	    for (let index = 0; index < positions.length; index += 1) {
636	      if (sheetPosition <= positions[index]) return index;
637	    }
638	    return null;
639	  }
